+@using sv_d92ff9e330d54a78ae88fea9acb5c2f5.Components.Chat
+@using sv_d92ff9e330d54a78ae88fea9acb5c2f5.Services
+@inject IChatService ChatService
+@rendermode InteractiveServer
+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-layout">
+    <div class="chat-sidebar">
+        <ChannelSidebar Channels="channels"
+                        ActiveChannelId="activeChannelId"
+                        OnChannelSelected="SelectChannel" />
+    </div>
+
+    <div class="chat-main @(threadOpen ? "with-thread" : "")">
+        @if (activeChannel is not null)
+        {
+            <MessageArea ChannelName="@activeChannel.Name"
+                         ChannelDescription="@activeChannel.Description"
+                         Messages="messages"
+                         ThreadSummaries="threadSummaries"
+                         IsLoadingMore="isLoadingMore"
+                         OnOpenThread="OpenThread"
+                         OnReact="HandleReaction"
+                         OnSendMessage="SendMessage"
+                         OnLoadMore="LoadMoreMessages" />
+        }
+        else
+        {
+            <div class="empty-state">
+                <p>Select a channel to start chatting</p>
+            </div>
+        }
+    </div>
+
+    @if (threadOpen && threadRootMessage is not null)
+    {
+        <div class="chat-thread">
+            <ThreadPanel RootMessage="threadRootMessage"
+                         Replies="threadReplies"
+                         OnClose="CloseThread"
+                         OnReply="SendThreadReply" />
+        </div>
+    }
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private List<Message> messages = [];
+    private List<ThreadSummary> threadSummaries = [];
+    private List<Message> threadReplies = [];
+    private Channel? activeChannel;
+    private int activeChannelId;
+    private Message? threadRootMessage;
+    private bool threadOpen;
+    private bool isLoadingMore;
+    private int messageSkip;
+    private const int PageSize = 30;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        activeChannelId = channelId;
+        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        messageSkip = 0;
+        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        messageSkip = messages.Count;
+
+        // Build thread summaries from messages that have replies
+        threadSummaries = messages
+            .Where(m => m.ReplyToId is null)
+            .Select(m => new ThreadSummary(m.Id, messages.Count(r => r.ReplyToId == m.Id), m.SentAt))
+            .Where(t => t.ReplyCount > 0)
+            .ToList();
+
+        await ChatService.MarkChannelReadAsync(channelId);
+
+        // Update the channel's unread count locally
+        var idx = channels.FindIndex(c => c.Id == channelId);
+        if (idx >= 0)
+        {
+            channels[idx] = channels[idx] with { UnreadCount = 0 };
+        }
+
+        CloseThread();
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        if (isLoadingMore || activeChannel is null) return;
+        isLoadingMore = true;
+        StateHasChanged();
+
+        var olderMessages = await ChatService.GetMessagesAsync(activeChannel.Id, messageSkip, PageSize);
+        if (olderMessages.Count > 0)
+        {
+            messages.InsertRange(0, olderMessages);
+            messageSkip += olderMessages.Count;
+        }
+
+        isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (activeChannel is null) return;
+        var message = await ChatService.SendMessageAsync(activeChannel.Id, content, null);
+        messages.Add(message);
+    }
+
+    private async Task OpenThread(int messageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
+        if (threadRootMessage is null) return;
+
+        threadReplies = await ChatService.GetThreadAsync(messageId);
+        threadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        threadOpen = false;
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (threadRootMessage is null || activeChannel is null) return;
+        var reply = await ChatService.SendMessageAsync(activeChannel.Id, content, threadRootMessage.Id);
+        threadReplies.Add(reply);
+        messages.Add(reply);
+
+        // Update thread summary
+        var existing = threadSummaries.FindIndex(t => t.RootMessageId == threadRootMessage.Id);
+        if (existing >= 0)
+        {
+            threadSummaries[existing] = threadSummaries[existing] with
+            {
+                ReplyCount = threadSummaries[existing].ReplyCount + 1,
+                LastReplyAt = reply.SentAt
+            };
+        }
+        else
+        {
+            threadSummaries.Add(new ThreadSummary(threadRootMessage.Id, 1, reply.SentAt));
+        }
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Update local message state
+        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId);
+        if (msg is not null)
+        {
+            var reaction = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
+            if (reaction is not null)
+            {
+                reaction.Users.Add("You");
+            }
+            else
+            {
+                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
+            }
+        }
+    }
+}
+

